#!/usr/bin/env node
/**
 * Scan TARGET markets — counties added from the app's Markets finder
 * ("Add to targets"). Same Redfin lane as bin/scan.mjs, but the polygon
 * comes from the markets table (generated by mf-calc bboxPolygon at
 * add time) instead of lib/markets.js.
 *
 * Invoked automatically after the morning phoenix scan (see scan.mjs);
 * runnable by hand: node bin/targets.mjs [--max 6]
 */
import { gisCsvUrl, fetchGisCsv } from '../lib/redfin.js';
import { listingsFromCSV } from '../lib/csv.js';
import { pullWithBands } from '../lib/bands.js';
import { makeDb } from '../lib/db.js';

function arg(name, dflt) {
  const i = process.argv.indexOf(`--${name}`);
  if (i < 0) return dflt;
  const v = process.argv[i + 1];
  return v && !v.startsWith('--') ? v : true;
}
const MAX = Number(arg('max', 6));

const db = makeDb();
const orgId = await db.resolveOrgId();

const { data: targets, error } = await db.supabase
  .from('markets')
  .select('id, name, state, geo_id, poly')
  .eq('org_id', orgId)
  .eq('scan_enabled', true)
  .not('poly', 'is', null)
  .limit(MAX);
if (error) throw error;
if (!targets?.length) {
  console.log('No scan-enabled target markets — nothing to do.');
  process.exit(0);
}
console.log(`Scanning ${targets.length} target market(s): ${targets.map((t) => t.name).join(', ')}`);

function bandFetcher(poly, statuses) {
  return async (min, max) => {
    const url = gisCsvUrl({
      poly,
      statuses,
      soldWithinDays: statuses.sold ? 365 : undefined,
      minPrice: min > 0 ? min : undefined,
      maxPrice: max < 200_000_000 ? max : undefined,
    });
    const res = await fetchGisCsv(url);
    if (!res.ok) return { ok: false, blocked: res.blocked, listings: [] };
    const { listings } = listingsFromCSV(res.text);
    return { ok: true, blocked: false, listings };
  };
}

let anyBlocked = false;
for (const t of targets) {
  if (anyBlocked) break; // stop-on-block applies to the whole run
  console.log(`\n→ ${t.name}, ${t.state}`);
  const runId = await db.startScanRun(orgId, `target-${t.name}`, 'both');
  try {
    const act = await pullWithBands(
      bandFetcher(t.poly, { active: true, pending: true, comingsoon: true, contingent: true }),
    );
    anyBlocked = anyBlocked || act.blocked;
    const active = act.listings.filter((l) => l.status !== 'sold');
    if (active.length) await db.upsertActiveDeals(orgId, active);

    let soldCount = 0;
    if (!anyBlocked) {
      const sold = await pullWithBands(bandFetcher(t.poly, { sold: true }));
      anyBlocked = anyBlocked || sold.blocked;
      soldCount = sold.listings.length;
      if (soldCount) await db.upsertComps(orgId, sold.listings);
    }

    await db.finishScanRun(runId, {
      ok: !anyBlocked,
      blocked: anyBlocked,
      requests_made: act.requests,
      rows_fetched: active.length + soldCount,
      rows_active: active.length,
      rows_sold: soldCount,
      notes: `target scan ${t.geo_id || ''}`,
    });
    console.log(`  ${active.length} active → deals · ${soldCount} sold → comps${anyBlocked ? ' · BLOCKED' : ''}`);
  } catch (e) {
    await db
      .finishScanRun(runId, { ok: false, blocked: false, rows_fetched: 0, rows_active: 0, rows_sold: 0, notes: `FAILED: ${e.message}`.slice(0, 2000) })
      .catch(() => {});
    console.error(`  ✗ ${t.name}: ${e.message}`);
  }
}

if (anyBlocked) {
  console.error('\n✗ Redfin block encountered — stopped. Remaining targets run tomorrow.');
  process.exit(2);
}
console.log('\n✓ Target scans complete.');
